replacements.new:
if (f_ddr_w) {
    // A same-cycle AW/W pair is legal: the pre-edge caw_q is still
    // empty, but the post-edge mutation will push this AW before it
    // applies the W beat.  Count against a temporary entry seeded
    // from the accepted AW signals; never mutate the real queue here.
    if (!caw_q.empty()) {
        const CawEnt& c = caw_q.front();   // BEFORE mutate / pop
        if (((c.id >> 4) & 3u) == 2u) {
            const int reg = nat_pregion(c.addr);
            const uint64_t baddr = c.addr + (uint64_t)c.got * 8ULL;
            ++n_nat_pw;
            ++nat_pw_beats[reg];
            nat_emit(s_ddr_w_l ? "pwlast" : "pw", reg, c.id, baddr,
                     c.len, c.got, s_ddr_w_l);
        }
    } else if (f_ddr_aw) {
        CawEnt c;                  // temporary, not the real queue
        c.id   = s_ddr_aw_i;
        c.addr = s_ddr_aw_a;
        c.len  = (uint8_t)s_ddr_aw_l;
        c.got  = 0;
        if (((c.id >> 4) & 3u) == 2u) {
            const int reg = nat_pregion(c.addr);
            const uint64_t baddr = c.addr + (uint64_t)c.got * 8ULL;
            ++n_nat_pw;
            ++nat_pw_beats[reg];
            nat_emit(s_ddr_w_l ? "pwlast" : "pw", reg, c.id, baddr,
                     c.len, c.got, s_ddr_w_l);
        }
    } else {
        CHECK(false,
              "natural: DDR W beat with no pending completion AW "
              "and no same-cycle accepted AW");
    }
}
